code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pairs = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    pairs.add((r, c, rr, cc, color))
    for r1, c1, r2, c2, color in pairs:
        dr, dc = r2-r1, c2-c1
        for r, c, sr, sc in ((r1,c1,-dr,-dc),(r2,c2,dr,dc)):
            rr, cc = r+sr, c+sc
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                out[rr][cc] = color
                rr += sr; cc += sc
    return out
'''
